INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('00daa905-2060-4b9c-8369-eb5e6878f6a6'::uuid, 'card_description', 'Rivers wrap Burnt Fen on three sides: low-lying prime farmland between Littleport and Mildenhall, where a remarkable amount of Mesolithic archaeology has come to light.', 'Mesolithic finds show up in a remarkable amount across this low-lying land. Rivers hem the ground in on three sides, and a road now runs through the prime farmland.', 'teaser-card-s037:00daa905-2060-4b9c-8369-eb5e6878f6a6:card_description', 'teaser-card-s037 (teaser-card): teaser card, 164 characters, checked PASS, web-verified VERIFIED', 'ca5c9ea8195b6cbcf9b9449d977a030ca083238e06480dc86931fe7d96e2830a|8c848bf9cb02819901d64fbf1a965d70698355cadf76dab7d9e7a586eff108cf|8c848bf9cb02819901d64fbf1a965d70698355cadf76dab7d9e7a586eff108cf', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Mesolithic finds show up in a remarkable amount across this low-lying land. Rivers hem the ground in on three sides, and a road now runs through the prime farmland."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Mesolithic archaeological finds have been made here [S4]; the finds occur in a remarkable amount [S4]; the area is low-lying land [S1]; rivers surround the land on three sides [S2]; a road currently runs through the area [S1]; the land is prime farmland [S2]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Burnt Fen is hemmed in on three sides by rivers [SUPPORTED: https://en.wikipedia.org/wiki/Burnt_Fen]; Mesolithic finds have been made at Burnt Fen [SUPPORTED: https://www.cambridge.org/core/journals/proceedings-of-the-prehistoric-society/article/abs/mesolithic-and-neolithic-activity-and-environmental-impact-on-the-southeast-fenedge-in-cambridgeshire/D38C6B342A5639B046D24E57ADAA9911]; The Mesolithic finds show up across the land, not at one spot only [SUPPORTED: https://www.cambridge.org/core/journals/proceedings-of-the-prehistoric-society/article/abs/mesolithic-and-neolithic-activity-and-environmental-impact-on-the-southeast-fenedge-in-cambridgeshire/D38C6B342A5639B046D24E57ADAA9911]; The amount of these (Stone Age) finds is remarkable [SUPPORTED: https://en.wikipedia.org/wiki/Mildenhall,_Suffolk]; The land is low-lying [SUPPORTED: https://en.wikipedia.org/wiki/Shippea_Hill_railway_station]; A road now runs through the land [SUPPORTED: https://en.wikipedia.org/wiki/Burnt_Fen]; The land is prime farmland [SUPPORTED: https://en.wikipedia.org/wiki/Burnt_Fen]"}]'::jsonb),
    ('03ae634b-9c91-450a-89eb-9e9f79bdb726'::uuid, 'card_description', '4th millennium BC kurgan cemetery — the oldest known in Transcaucasia. Nine mounds discovered in 2006 by a joint French-led team, linked to similar kurgans at Kavtiskhevi in the South Caucasus.', 'The earliest evidence of silver use in the Caucasus comes from this village. A team also found nine burial mounds here, the oldest mound cemetery in Transcaucasia.', 'teaser-card-s037:03ae634b-9c91-450a-89eb-9e9f79bdb726:card_description', 'teaser-card-s037 (teaser-card): teaser card, 163 characters, checked PASS, web-verified VERIFIED', '207e88a4e1d2a2fa50b5774aa1faebe51e831b4b142dea4a7934849261a86257|7f7686663c8b69622817f8cb4b07c8add5b265629582a22ef394b51a73b52825|7f7686663c8b69622817f8cb4b07c8add5b265629582a22ef394b51a73b52825', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "The earliest evidence of silver use in the Caucasus comes from this village. A team also found nine burial mounds here, the oldest mound cemetery in Transcaucasia."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "the earliest evidence of silver use in the Caucasus comes from this place [S4]; the place is a village [S1]; a team found burial mounds here [S1]; there are nine burial mounds [S1]; they form the oldest burial-mound cemetery in Transcaucasia [S1]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "The village''s kurgan (burial mound) cemetery is the oldest mound cemetery in Transcaucasia [SUPPORTED: https://intarch.ac.uk/journal/issue59/11/full-text.cfm]; The earliest evidence of silver use in the Caucasus comes from this village [SUPPORTED: http://saunje.ge/index.php?id=1533&lang=en&option=com_content]; Silver from here predates the first silver in neighbouring Georgia [SUPPORTED: http://saunje.ge/index.php?id=1533&lang=en&option=com_content]; A team found nine burial mounds here [SUPPORTED: https://ra.iaran.ru/?lang=en&page_id=3543]; The mound cemetery is older than mound burial was previously thought to be in Transcaucasia [SUPPORTED: https://ra.iaran.ru/?lang=en&page_id=3543]"}]'::jsonb),
    ('05133e1e-6d12-461c-a682-d8ac77d2550f'::uuid, 'card_description', 'Near Goni, around sixty menhirs stand in pairs, alignments and groups at the Necropolis of Pranu Muttedu, beside funerary chambers once covered by a tumulus and ringed by megalithic circles.', 'Stone blocks set in rings within rings once enclosed these burial chambers. Mounds once covered them, and around sixty standing stones rise in pairs, lines and groups.', 'teaser-card-s037:05133e1e-6d12-461c-a682-d8ac77d2550f:card_description', 'teaser-card-s037 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', '1ecceb9081a9f2f0fbdc8110d5df66e2a009581132decc087053b37c7909a9f9|d03e1b50452985d441483fbfcf17b403a80ff5d42c27d4335b416d7d79ab1077|d03e1b50452985d441483fbfcf17b403a80ff5d42c27d4335b416d7d79ab1077', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Stone blocks set in rings within rings once enclosed these burial chambers. Mounds once covered them, and around sixty standing stones rise in pairs, lines and groups."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "the site has burial chambers [S4]; the chambers were originally enclosed by circles of stone blocks [S4]; the blocks are arranged in concentric rings [S4]; mounds originally covered the chambers [S4]; there are around sixty standing stones [S2]; the standing stones are arranged in pairs, alignments and groups [S3]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Stone blocks set in rings within rings (concentric rings) once enclosed the burial chambers [SUPPORTED: https://www.sardegnaturismo.it/it/esplora/parco-di-pranu-muttedu]; The site has burial chambers [SUPPORTED: https://www.sardegnaturismo.it/it/esplora/parco-di-pranu-muttedu]; Mounds once covered the burial chambers [SUPPORTED: https://www.sardegnasacra.it/megalitismo-e-ipogeismo-a-pranu-mutteddu-goni-un-complesso-sacro-e-funerario-unico/]; Around sixty standing stones (menhirs) rise at the site [SUPPORTED: https://www.sardegnaturismo.it/it/esplora/parco-di-pranu-muttedu]; Some standing stones stand in pairs [SUPPORTED: https://www.sardegnaturismo.it/it/esplora/parco-di-pranu-muttedu]; Some standing stones stand in lines (alignments) [SUPPORTED: https://www.sardegnaturismo.it/it/esplora/parco-di-pranu-muttedu]; Some standing stones stand in groups [SUPPORTED: https://www.sardegnaturismo.it/it/esplora/parco-di-pranu-muttedu]"}]'::jsonb),
    ('109fcdea-c114-4143-87ac-77c4c9c20f16'::uuid, 'card_description', 'Hittite imperial capital from the 19th century BC, on a site settled since the 6th millennium BC. Modern identification restored knowledge of an empire whose existence had been entirely forgotten.', 'A rock shrine with remarkable carvings of gods stands near this Hittite capital. The site holds a large temple district, and digs since 1906 have yielded thousands of tablets.', 'teaser-card-s037:109fcdea-c114-4143-87ac-77c4c9c20f16:card_description', 'teaser-card-s037 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '878909a15df9c8e562f627212c6bc1ba9c1bba28db977bd696bf34f5bc078ec4|4873bfb79084189fe75397bb74b6380fd6c33875e926323bb9a5978b27575d13|4873bfb79084189fe75397bb74b6380fd6c33875e926323bb9a5978b27575d13', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "A rock shrine with remarkable carvings of gods stands near this Hittite capital. The site holds a large temple district, and digs since 1906 have yielded thousands of tablets."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "a rock sanctuary stands near the site [S2]; the sanctuary has remarkable relief carvings of gods [S2]; the site was a Hittite capital [S1]; the site contains a large temple district [S2]; excavations have run since 1906 [S3]; they have yielded thousands of tablets [S3]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "The site was the Hittite capital [SUPPORTED: https://en.wikipedia.org/wiki/Yaz%C4%B1l%C4%B1kaya]; A rock shrine stands near the capital [SUPPORTED: https://en.wikipedia.org/wiki/Yaz%C4%B1l%C4%B1kaya]; The rock shrine has remarkable carvings of gods [SUPPORTED: https://en.wikipedia.org/wiki/Yaz%C4%B1l%C4%B1kaya]; The site holds a large temple district [SUPPORTED: https://de.wikipedia.org/wiki/Hattu%C5%A1a]; Digs have taken place at the site since 1906 [SUPPORTED: https://de.wikipedia.org/wiki/Hattu%C5%A1a]; The digs have yielded thousands of tablets [SUPPORTED: https://de.wikipedia.org/wiki/Hattu%C5%A1a]"}]'::jsonb),
    ('1196cd92-ce30-4a47-97f4-51f7a3694ebc'::uuid, 'card_description', 'At the natural port of Sanitja lies Sanisera, a city Pliny the Elder mentioned. Amphorae of the 1st to 4th centuries AD were raised from its seabed, and 44 tombs lie in rows nearby.', 'Pliny the Elder wrote the first mention of this city by a natural port. Its seabed gave up storage jars from the 1st to the 4th centuries AD, and rows of tombs lie beside the port.', 'teaser-card-s037:1196cd92-ce30-4a47-97f4-51f7a3694ebc:card_description', 'teaser-card-s037 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '394a7594c9a11ce57052529970394b16fb148556e581af2e5df3bd70b5376a6e|04c6c0a1ae00afa4527feb8d00b5ec60a86a93372f99f7cc604f9a9fdafdbab6|04c6c0a1ae00afa4527feb8d00b5ec60a86a93372f99f7cc604f9a9fdafdbab6', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Pliny the Elder wrote the first mention of this city by a natural port. Its seabed gave up storage jars from the 1st to the 4th centuries AD, and rows of tombs lie beside the port."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Pliny the Elder wrote the first written mention of the city [S2]; the site is a city [S2]; the city lies at a natural port [S1]; amphorae (storage jars) were recovered from the seabed [S3]; the amphorae date from the 1st to the 4th centuries AD [S3]; tombs arranged in rows lie in the surroundings of the port [S6, S7]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Pliny the Elder wrote the first mention of this city [SUPPORTED: https://archaeology.institute/en/investigacion_fuentes.asp]; Pliny the Elder mentioned the city in his writing [SUPPORTED: https://archaeology.institute/en/investigacion_fuentes.asp]; The city lies by a natural port [SUPPORTED: https://archaeology.institute/en/2008_publi_book6_en.pdf]; The port''s seabed gave up storage jars (amphorae) [SUPPORTED: https://archaeology.institute/en/investigacion_hallazgos_casuales.asp]; The storage jars from the seabed date from the 1st to the 4th centuries AD [SUPPORTED: https://es.wikipedia.org/wiki/Sanisera]; Rows of tombs lie beside the port [SUPPORTED: https://www.balearesantigua.com/sanisera-necropolis-4/]"}]'::jsonb),
    ('1a9242d4-250f-4ffb-8dad-dae849c10798'::uuid, 'card_description', 'Near Chichen Itza, Balankanche Cave has drawn rituals to the Maya rain god Chaac for more than two thousand years. Inside were found stairs, altars and ritual displays of ceramics.', 'Rituals for the Maya rain god Chaac centred on this cave. Pottery finds point to ceremonies from 300 BC up to 1200, later also for his Toltec counterpart, Tlaloc.', 'teaser-card-s037:1a9242d4-250f-4ffb-8dad-dae849c10798:card_description', 'teaser-card-s037 (teaser-card): teaser card, 162 characters, checked PASS, web-verified VERIFIED', '4b1f260b21e24a64041c7160ec85efe256f8bc01116add983adeda6271caf66e|96a958075efd712c8c3728cf0830175c23644e29421c79c1559af1fcd0e31eb6|96a958075efd712c8c3728cf0830175c23644e29421c79c1559af1fcd0e31eb6', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Rituals for the Maya rain god Chaac centred on this cave. Pottery finds point to ceremonies from 300 BC up to 1200, later also for his Toltec counterpart, Tlaloc."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "the site is a cave [S1]; rituals for the Maya rain god Chaac were focused on this cave [S2]; pottery finds indicate ceremonies there from 300 BC up to AD 1200 [W1]; later (in the Post-Classic period) rituals were also dedicated to Tlaloc [S2]; Tlaloc is the Toltec counterpart of Chaac [S2]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Rituals for the Maya rain god Chaac centred on Balankanche Cave [SUPPORTED: https://lugares.inah.gob.mx/en/node/4372]; Pottery finds point to ceremonies held in the cave [SUPPORTED: https://lugares.inah.gob.mx/en/node/4372]; The ceremonies began by 300 BC [SUPPORTED: https://lugares.inah.gob.mx/en/node/4372]; The ceremonies continued up to 1200 (AD) [SUPPORTED: https://lugares.inah.gob.mx/en/node/4372]; Later, rituals in the cave were also held for Tlaloc [SUPPORTED: https://www.mexicolore.co.uk/maya/collaboration/balamkanche-altar-of-the-jaguar-priest]; Tlaloc is the Toltec counterpart of the Maya rain god Chaac [SUPPORTED: https://www.mexicolore.co.uk/maya/collaboration/balamkanche-altar-of-the-jaguar-priest]"}, {"source": "web fact W1", "url": "https://lugares.inah.gob.mx/en/node/4372", "quote": "Pottery finds indicate that the cave was used for ceremonies from 300 BC in the Late Preclassic up to 1200 in the Late Postclassic."}]'::jsonb),
    ('1da76491-5256-486f-b67e-ff6f762c46b5'::uuid, 'card_description', 'On the English Channel coast, High Peak rises to about 157 metres above sea-level. Geological study suggests the site once extended several tens of metres into what is now eroded away.', 'Several tens of metres of this hill fort may now be eroded away. Earthworks line the cliff edge, and the fort was perhaps reused in the Dark Ages as a coastal trading station.', 'teaser-card-s037:1da76491-5256-486f-b67e-ff6f762c46b5:card_description', 'teaser-card-s037 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '4d08873a6b05ae649dd47dca31b716a3ce16d8057ce9eba6d94a91b081535716|e9ee2bf36c0768aa4ec84a94f04a2746d4e568ce7bd48d2f64e399935ef3b4fc|e9ee2bf36c0768aa4ec84a94f04a2746d4e568ce7bd48d2f64e399935ef3b4fc', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Several tens of metres of this hill fort may now be eroded away. Earthworks line the cliff edge, and the fort was perhaps reused in the Dark Ages as a coastal trading station."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "the site is a hill fort [S3]; several tens of metres of the site are probably now eroded away (hedged: may) [S5]; earthworks lie along the cliff edge [S4]; the fort was perhaps reused in the Dark Ages [S4, S6]; the reuse was perhaps as a coastal trading station [S6]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "The site on High Peak, Devon, is a hill fort, partly eroded away [SUPPORTED: https://intarch.ac.uk/journal/issue3/snyder/gaznew.html]; Several tens of metres of the hill fort may now be eroded away (hedged ''may'') [SUPPORTED: https://coastalandgeotechnicalservices.com/assets/docs/SOBC-Case_Study_5-South-West_England-Part_1.19185531.pdf]; Earthworks of the fort line the cliff edge [SUPPORTED: https://en.wikipedia.org/wiki/Otterton]; The fort was in use in the Dark Ages (post-Roman period) [SUPPORTED: https://intarch.ac.uk/journal/issue3/snyder/gaznew.html]; The Dark Age fort was perhaps a reuse of an earlier (Iron Age) fort (hedged ''perhaps''; the excavation summaries identify only sub-Roman ramparts, so sources differ and the hedge is needed) [SUPPORTED: https://en.wikipedia.org/wiki/Otterton]; In the Dark Ages the fort perhaps served as a coastal trading station (hedged ''perhaps'') [SUPPORTED: https://intarch.ac.uk/journal/issue3/snyder/gaznew.html]"}]'::jsonb),
    ('28b7b9c1-3901-4762-a71f-353d6ba8b513'::uuid, 'card_description', 'North of Doncaster, the bridleway of Roman Ridge was part of Ermine Street, a Roman road. It runs past Scawsby and Highfields to the Great North Road, then joins the A1 as far as Barnsdale.', 'Ermine Street, a Roman road, once ran along this bridleway. Today the path cuts in half the angle between two modern roads, then skirts two villages to meet the Great North Road.', 'teaser-card-s037:28b7b9c1-3901-4762-a71f-353d6ba8b513:card_description', 'teaser-card-s037 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', 'c801fe5e5146cc8d77708d73e391f18c91b97664455dacce824760960b55db42|b8f9c0e5fc4d06eb2d21ae5033ed23fa9991b1d716b700fdd24b5602460a485a|b8f9c0e5fc4d06eb2d21ae5033ed23fa9991b1d716b700fdd24b5602460a485a', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Ermine Street, a Roman road, once ran along this bridleway. Today the path cuts in half the angle between two modern roads, then skirts two villages to meet the Great North Road."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "the site is a bridleway [S1]; the bridleway was part of Ermine Street [S1]; Ermine Street was a Roman road [S1]; the path''s course currently bisects the angle between two modern roads [S2, S3]; the path then runs along the edge of two villages [S5]; it reaches the Great North Road [S5]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "The Roman road ran along the line of this bridleway north of Doncaster (the Roman Ridge) [SUPPORTED: https://roadsofromanbritain.org/gazetteer/yorkshire/rr28b.html]; The Roman road along the Roman Ridge is Ermine Street [SUPPORTED: https://en.wikipedia.org/wiki/Woodlands,_South_Yorkshire]; Ermine Street is a Roman road [SUPPORTED: https://en.wikipedia.org/wiki/Ermine_Street]; The route is today a path (bridleway) [SUPPORTED: https://roadsofromanbritain.org/gazetteer/yorkshire/rr28b.html]; The path runs between two modern roads, starting at their junction (A638 and A635) [SUPPORTED: https://en.wikipedia.org/wiki/Adwick_le_Street]; The path cuts in half (bisects) the angle between the two modern roads [UNVERIFIABLE, no proving quote: None]; The path skirts two villages (Highfields and Woodlands) [SUPPORTED: https://en.wikipedia.org/wiki/Highfields,_South_Yorkshire]; The path meets the Great North Road [SUPPORTED: https://en.wikipedia.org/wiki/Adwick_le_Street]"}]'::jsonb),
    ('31c676cd-4f5c-4e40-9bed-9c998f69eb81'::uuid, 'card_description', 'An ancient Sallentini town named Castrum Minervae -- "Athena''s Castle." Legend says the Greek hero Idomeneus founded both the tribe and its temple of Minerva.', 'Virgil has Aeneas, fleeing Troy, first land in this country at this old town. Digs uncovered a sanctuary of Athena, with a 12-cm bronze statue of her in a Phrygian helmet.', 'teaser-card-s037:31c676cd-4f5c-4e40-9bed-9c998f69eb81:card_description', 'teaser-card-s037 (teaser-card): teaser card, 171 characters, checked PASS, web-verified VERIFIED', 'f76b728095ba755ef8a800e3283db3c8c97814ce86b3e38824ea6e4e3ffe557e|234c2d24f6158be48d6b4ebc204de235d29ebd8d3a3286aac909cb551482bd70|234c2d24f6158be48d6b4ebc204de235d29ebd8d3a3286aac909cb551482bd70', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Virgil has Aeneas, fleeing Troy, first land in this country at this old town. Digs uncovered a sanctuary of Athena, with a 12-cm bronze statue of her in a Phrygian helmet."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Virgil names this place as Aeneas''s first landfall in the country [S1]; Aeneas was fleeing Troy [S1]; the site is an old town (an ancient settlement) [S1, S2]; excavations uncovered a sanctuary of Athena [S3]; the finds include a 12-cm bronze statue of the goddess [S3]; the statue shows her wearing a Phrygian helmet [S3]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "In Virgil''s Aeneid, Aeneas makes his first landing in Italy at this town (Castro, ancient Castrum Minervae) [SUPPORTED: https://www.aeneasroute.org/en/tour/castro/]; Aeneas was fleeing Troy [SUPPORTED: https://en.wikipedia.org/wiki/Aeneid]; Castro is an old (ancient) town [SUPPORTED: https://www.aeneasroute.org/en/tour/castro/]; Excavations uncovered a sanctuary of Athena at Castro [SUPPORTED: https://www.aeneasroute.org/en/tour/castro/]; The digs found a bronze statue of Athena [SUPPORTED: https://www.aeneasroute.org/en/tour/castro/]; The bronze statue is 12 cm high [SUPPORTED: https://www.aeneasroute.org/en/tour/castro/]; The bronze Athena wears a Phrygian helmet [SUPPORTED: https://www.aeneasroute.org/en/tour/castro/]"}]'::jsonb),
    ('3b04e370-3686-477d-a5c1-f1a6f7123c5f'::uuid, 'card_description', 'Southeast of the weathered granite of Hound Tor on Dartmoor lie the ruins of Hundatorra, a deserted medieval village of longhouses, built on land farmed originally in the Bronze Age.', 'A deserted medieval village lies beside a heavily weathered granite outcrop. The village rose on land originally farmed in the Bronze Age, and maybe grazed in the Roman period.', 'teaser-card-s037:3b04e370-3686-477d-a5c1-f1a6f7123c5f:card_description', 'teaser-card-s037 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '89a60d7564a7ce74c9201c4e5c6016d648e91da7d954f8689176911a92bd932f|0ae865b3100c046203acf95de47e4aafeb0853d17196202669ef7cfc314c100d|0ae865b3100c046203acf95de47e4aafeb0853d17196202669ef7cfc314c100d', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "A deserted medieval village lies beside a heavily weathered granite outcrop. The village rose on land originally farmed in the Bronze Age, and maybe grazed in the Roman period."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "there is a deserted village at the site [S3]; the village is medieval [S3]; the village lies beside (near) the outcrop [S2, S3]; the outcrop is granite [S1]; the outcrop is heavily weathered [S1]; the village was built on land originally farmed in the Bronze Age [S4]; the land may have been used for grazing in the Roman period (hedge kept as ''maybe'') [S4]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "A deserted medieval village (Hound Tor deserted medieval village) lies beside the outcrop of Hound Tor [SUPPORTED: https://www.english-heritage.org.uk/visit/places/hound-tor-deserted-medieval-village/history/]; The village is medieval [SUPPORTED: https://www.english-heritage.org.uk/visit/places/hound-tor-deserted-medieval-village/history/]; The village was deserted [SUPPORTED: https://www.english-heritage.org.uk/visit/places/hound-tor-deserted-medieval-village/history/]; The village lies right beside the outcrop [SUPPORTED: https://www.english-heritage.org.uk/visit/places/hound-tor-deserted-medieval-village/history/]; The outcrop is granite [SUPPORTED: https://www.english-heritage.org.uk/visit/places/hound-tor-deserted-medieval-village/history/]; The granite outcrop is heavily weathered [SUPPORTED: https://www.english-heritage.org.uk/visit/places/hound-tor-deserted-medieval-village/history/]; The village rose on land originally farmed in the Bronze Age [SUPPORTED: https://www.english-heritage.org.uk/visit/places/hound-tor-deserted-medieval-village/history/]; The land was maybe grazed in the Roman period [SUPPORTED: https://www.english-heritage.org.uk/visit/places/hound-tor-deserted-medieval-village/history/]"}]'::jsonb),
    ('3c1e886f-d77b-4d46-899b-2aaf26861a4d'::uuid, 'card_description', 'From 1973 to 2000 Ihor Gereta investigated the Burial Ground of Cherneliv-Ruskyi, finding Chernyakhov, Kievan Rus'' and Pomeranian burials and one unidentified, probably from the Bronze Age.', 'One grave here, not identified, probably dates from the Bronze Age. Digs by Ihor Gereta found 315 burials in all, among them 24 from Kievan Rus'' and two Pomeranian ones.', 'teaser-card-s037:3c1e886f-d77b-4d46-899b-2aaf26861a4d:card_description', 'teaser-card-s037 (teaser-card): teaser card, 169 characters, checked PASS, web-verified VERIFIED', '5e952dc44e6bfdadd22e15b5ff321b2edb6c828f4277d5630286fedca89baab2|ff262924b8d813e73ec4e82be160f8f3fea15d3d43e281b7b1d9d51f657a93a4|ff262924b8d813e73ec4e82be160f8f3fea15d3d43e281b7b1d9d51f657a93a4', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "One grave here, not identified, probably dates from the Bronze Age. Digs by Ihor Gereta found 315 burials in all, among them 24 from Kievan Rus'' and two Pomeranian ones."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "one grave here is unidentified [S4]; that grave probably dates from the Bronze Age [S4]; Ihor Gereta led the excavations [S3, S4]; 315 burials were found in all [S4]; 24 of them are from Kievan Rus'' [S4]; two of them are Pomeranian [S4]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Excavations at this burial ground found 315 burials in all [SUPPORTED: https://irp.te.ua/mogylnyk-chernyahivskoyi-kultury-cherneliv-ruskyj/]; The digs were led by Ihor Gereta [SUPPORTED: https://irp.te.ua/mogylnyk-chernyahivskoyi-kultury-cherneliv-ruskyj/]; 24 of the burials date from Kievan Rus'' [SUPPORTED: https://nasplib.isofts.kiev.ua/server/api/core/bitstreams/719a58cd-9b2c-48d1-8a85-4ea31cbaaff7/content]; Two of the burials are Pomeranian (Pomeranian culture) [SUPPORTED: https://nasplib.isofts.kiev.ua/server/api/core/bitstreams/719a58cd-9b2c-48d1-8a85-4ea31cbaaff7/content]; One grave probably dates from the Bronze Age [SUPPORTED: https://nasplib.isofts.kiev.ua/server/api/core/bitstreams/719a58cd-9b2c-48d1-8a85-4ea31cbaaff7/content]; That one grave is not identified (its culture is uncertain) [SUPPORTED: https://nasplib.isofts.kiev.ua/server/api/core/bitstreams/719a58cd-9b2c-48d1-8a85-4ea31cbaaff7/content]"}]'::jsonb),
    ('4599daa4-93cc-4c55-872c-41e9c7875a59'::uuid, 'card_description', 'Carved from the Giza bedrock around 2558–2532 BC, this limestone sphinx is 73 metres long and 20 metres tall. The oldest monumental sculpture of its age, it represents the pharaoh Khafre.', 'About 73 metres long, a reclining lion with a human head wears a royal headdress. By one estimate, 100 workers spent three years carving the figure with stone hammers and copper chisels.', 'teaser-card-s037:4599daa4-93cc-4c55-872c-41e9c7875a59:card_description', 'teaser-card-s037 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'a4639b85401d76f1597a4761b2dde91f33a7078dbcb7205be62f133d9f52ec3d|71b37a9d2d00efc9ff7a720c70d74f3a384d86f361f4dce0ba7473c846a5af08|71b37a9d2d00efc9ff7a720c70d74f3a384d86f361f4dce0ba7473c846a5af08', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "About 73 metres long, a reclining lion with a human head wears a royal headdress. By one estimate, 100 workers spent three years carving the figure with stone hammers and copper chisels."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "the figure is about 73 metres long [S2]; it depicts a reclining lion [S2]; the lion has a human head [S2]; the head wears a royal headdress [S2]; by an estimate, 100 workers carved it [S4]; by that estimate the carving took three years [S4]; they used stone hammers and copper chisels [S4]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "The Great Sphinx of Giza is a reclining (recumbent) lion with a human head [SUPPORTED: https://www.memphis.edu/egypt/resources/colortour/giza4.php]; It is about 73 metres long [SUPPORTED: https://www.memphis.edu/egypt/resources/colortour/giza4.php]; The head wears a royal headdress [SUPPORTED: https://www.memphis.edu/egypt/resources/colortour/giza4.php]; By one estimate, 100 workers carved the figure [SUPPORTED: https://www.pbs.org/wgbh/nova/transcripts/3703_sphinx.html]; By that estimate, the carving took three years [SUPPORTED: https://www.pbs.org/wgbh/nova/transcripts/3703_sphinx.html]; The figure was carved with stone hammers [SUPPORTED: https://www.pbs.org/wgbh/nova/transcripts/3703_sphinx.html]; The figure was carved with copper chisels [SUPPORTED: https://www.pbs.org/wgbh/nova/transcripts/3703_sphinx.html]"}]'::jsonb),
    ('4bf50d9c-aa7f-4283-83d6-5519e1793a03'::uuid, 'card_description', 'On Aegina, the Temple of Aphaia honoured a goddess worshipped at this sanctuary alone. It rose circa 500 BC over the remains of an earlier temple destroyed by fire circa 510 BC.', 'Fire destroyed an earlier temple of this island sanctuary. Around 500 BC a new temple rose over the remains, and the new temple''s pediment sculptures are now on display in Munich.', 'teaser-card-s037:4bf50d9c-aa7f-4283-83d6-5519e1793a03:card_description', 'teaser-card-s037 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '6daf1957057f3a1f1aa56ba42878ac6f677583b5447f1c3e59af70f6ba3f4ea9|c4f1f2f3332e198e5c2e50bc07cef780f09f30a5ad64eabdfb09fa2aa1648a00|c4f1f2f3332e198e5c2e50bc07cef780f09f30a5ad64eabdfb09fa2aa1648a00', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Fire destroyed an earlier temple of this island sanctuary. Around 500 BC a new temple rose over the remains, and the new temple''s pediment sculptures are now on display in Munich."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "the site is a sanctuary on an island [S1]; an earlier temple of the sanctuary was destroyed by fire [S4]; around 500 BC a new temple was built [S4]; the new temple was built over the remains of the earlier one [S4]; the new temple had pediment sculptures [S5]; those pediment sculptures are now on display in Munich [S6]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "The pediment sculptures of the new Temple of Aphaia are now on display in Munich [SUPPORTED: https://webhelper.brown.edu/joukowsky/courses/greekpast/4775.html]; The sanctuary is on an island (Aegina) [SUPPORTED: http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=535]; An earlier temple of the sanctuary was destroyed by fire [SUPPORTED: http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=535]; The new temple was built around 500 BC [SUPPORTED: http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=535]; The new temple rose over the remains of the earlier one (on the same site) [SUPPORTED: http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=535]; The Munich sculptures are pediment sculptures of the temple [SUPPORTED: http://odysseus.culture.gr/h/2/eh251.jsp?obj_id=535]"}]'::jsonb),
    ('4df3dcbd-62d3-4e37-92fe-e79989233f1f'::uuid, 'card_description', 'In a canyon of the Sierra Libre, La Pintada holds cave paintings and rock engravings, while on the plain outside lie traces of seasonal camps strewn with ceramics and stone tools.', 'No site of the Central Coast tradition known so far lies farther from the coastline. Paintings and engravings mark the canyon, and camps on the plain outside left pottery and stone tools.', 'teaser-card-s037:4df3dcbd-62d3-4e37-92fe-e79989233f1f:card_description', 'teaser-card-s037 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'e463c8403f7c3f737d0ea3d2f3ba813b9bec2c8f32786ca5bb5f8dec123a543e|b64bd62db236cfbec60d4a902f3704f063d382c53175dc5896dcaf93db201b30|b64bd62db236cfbec60d4a902f3704f063d382c53175dc5896dcaf93db201b30', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "No site of the Central Coast tradition known so far lies farther from the coastline. Paintings and engravings mark the canyon, and camps on the plain outside left pottery and stone tools."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "the site belongs to (is associated with) the Central Coast archaeological tradition [S3, S4]; so far, no known site of that tradition lies farther from the coastline [S4]; there are paintings in the canyon [S2]; there are engravings in the canyon [S2]; there were camps on the plain outside the canyon [S2]; the camps left pottery [S2]; the camps left stone tools [S2]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "No site of the Central Coast tradition known so far lies farther from the coastline than this site (La Pintada). [SUPPORTED: https://arqueologiamexicana.mx/mexico-antiguo/la-pintada-sonora-voces-en-el-viento-senales-en-tierra-y-roca]; The site belongs to (is associated with) the Central Coast archaeological tradition. [SUPPORTED: https://arqueologiamexicana.mx/mexico-antiguo/la-pintada-sonora-voces-en-el-viento-senales-en-tierra-y-roca]; The site lies in a canyon. [SUPPORTED: https://www.inah.gob.mx/foto-del-dia/la-pintada-santuario-rupestre-en-el-desierto-de-sonora]; Paintings mark the canyon. [SUPPORTED: https://www.inah.gob.mx/foto-del-dia/la-pintada-el-sitio-rupestre-mas-representativo-de-sonora]; Engravings mark the canyon (paintings and engravings lie inside the canyon). [SUPPORTED: https://arqueologiamexicana.mx/mexico-antiguo/la-pintada-sonora-voces-en-el-viento-senales-en-tierra-y-roca]; There were camps on the plain outside the canyon. [SUPPORTED: https://arqueologiamexicana.mx/mexico-antiguo/la-pintada-sonora-voces-en-el-viento-senales-en-tierra-y-roca]; The camps left pottery. [SUPPORTED: https://www.inah.gob.mx/foto-del-dia/la-pintada-santuario-rupestre-en-el-desierto-de-sonora]; The camps left stone tools. [SUPPORTED: https://www.inah.gob.mx/foto-del-dia/la-pintada-el-sitio-rupestre-mas-representativo-de-sonora]"}]'::jsonb),
    ('77a54c05-fd61-4fd7-ae4b-4a0fc89fec53'::uuid, 'card_description', 'A Medusa mosaic and two buildings with hypocausts came to light at Dalton Parlours Roman Villa near Collingham, and beneath the villa lay something older still: an Iron Age site.', 'A mosaic of Medusa turned up in the early digs at this Roman villa. Those digs also found two buildings with underfloor heating, and modern digs found an Iron Age site beneath the villa.', 'teaser-card-s037:77a54c05-fd61-4fd7-ae4b-4a0fc89fec53:card_description', 'teaser-card-s037 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '9ea5407338524e36f71935ae90bbc4c8d075f5bc7dd8f775fbe1d55823a4944b|d27bfb562e5f8be4cbf52a76dd2179072995eb24078d3745c459326149297feb|d27bfb562e5f8be4cbf52a76dd2179072995eb24078d3745c459326149297feb', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "A mosaic of Medusa turned up in the early digs at this Roman villa. Those digs also found two buildings with underfloor heating, and modern digs found an Iron Age site beneath the villa."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "the site is a Roman villa [S1]; the early (initial) excavations found a Medusa mosaic [S3]; the early excavations also found two buildings [S3]; those two buildings had underfloor heating (hypocausts) [S3]; modern excavations found an Iron Age site [S5]; the Iron Age site lies beneath the villa [S5]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "A mosaic of Medusa was found in the early (19th-century) digs at Dalton Parlours Roman villa [SUPPORTED: https://www.wetherbycivicsociety.org.uk/dalton-parlours/]; The site is a Roman villa [SUPPORTED: https://www.wetherbycivicsociety.org.uk/dalton-parlours/]; Villa buildings had underfloor heating (hypocausts) [SUPPORTED: https://www.wetherbycivicsociety.org.uk/dalton-parlours/]; The early (19th-century) digs found two buildings with underfloor heating [UNVERIFIABLE, no proving quote: None]; Modern digs found an Iron Age site [SUPPORTED: https://www.wetherbycivicsociety.org.uk/dalton-parlours/]; The Iron Age site lies beneath (on the same site as) the villa [SUPPORTED: https://www.yfanefa.com/record/4997]"}]'::jsonb),
    ('7a1fc276-f5b2-42d1-b57f-95f2dc6eb115'::uuid, 'card_description', 'About 500 m south of the main square of Ambo, in the Huánuco Region, the cave of Hatun Uchku holds archaeological and paleontological remains, declared a National Cultural Heritage in 2002.', 'Fossils and traces of people turn up in this cave. In 2002 the cave was declared National Cultural Heritage, and the cave lies about 500 m south of a town''s main square.', 'teaser-card-s037:7a1fc276-f5b2-42d1-b57f-95f2dc6eb115:card_description', 'teaser-card-s037 (teaser-card): teaser card, 169 characters, checked PASS, web-verified VERIFIED', '17b629e3fffd79c149ef83d29d3ad868a816b2c89075cbdf79a3358219dc21cc|419466772304f57f9446136275558ae54c9c3d4ac0c424ef55ad87de3639cd01|419466772304f57f9446136275558ae54c9c3d4ac0c424ef55ad87de3639cd01', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Fossils and traces of people turn up in this cave. In 2002 the cave was declared National Cultural Heritage, and the cave lies about 500 m south of a town''s main square."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "the site is a cave [S1]; the cave holds fossils (paleontological remains) [S1]; the cave holds traces of people (archaeological remains) [S1]; the cave was declared National Cultural Heritage [S2]; the declaration was made in 2002 [S2]; the cave lies about 500 m south of a town''s main square [S3]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Fossils turn up in Hatun Uchku (Jatun Uchco/Ushco) cave [SUPPORTED: http://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=2368]; Traces of people turn up in the cave [SUPPORTED: http://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=2368]; The site is a cave [SUPPORTED: http://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=2368]; The cave was declared National Cultural Heritage [SUPPORTED: http://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=2368]; The declaration was made in 2002 [SUPPORTED: http://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=2368]; The cave lies about 500 m south of a town''s (Ambo''s) main square [SUPPORTED: https://www.deperu.com/sitios-naturales/cavernas-y-cuevas/cueva-de-jatun-uchco-550]"}]'::jsonb),
    ('7d8df981-b89f-4d88-809d-205d2d11c160'::uuid, 'card_description', 'On the banks of the Guruchay River, Taghlar Cave was home to Mousterian people 64-24 thousand years ago. Digging yielded more than 7,000 stone tools and remains of horse, deer and bull.', 'More than 7,000 stone tools have been dug from this riverside cave. Stone Age people lived in the cave, and one of its six layers held remains of mammals such as horse, noble deer and bull.', 'teaser-card-s037:7d8df981-b89f-4d88-809d-205d2d11c160:card_description', 'teaser-card-s037 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '2ce4990d8dc08162134f088dc3ecbd1f695ea5e6f19131f6fb54046de5dd68ea|b2a357c28343359cbaf7b52d1b53bb269607211f9b7c4aad1d5cadd3d1b6fcf2|b2a357c28343359cbaf7b52d1b53bb269607211f9b7c4aad1d5cadd3d1b6fcf2', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-write-002", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "More than 7,000 stone tools have been dug from this riverside cave. Stone Age people lived in the cave, and one of its six layers held remains of mammals such as horse, noble deer and bull."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "more than 7,000 stone tools were dug from the cave [S5]; the cave is by a river [S2]; Stone Age (Paleolithic) people lived in the cave [S1, S3]; the cave has six layers [S5]; one layer held mammal remains [S7]; the mammals include horse, noble deer and bull [S7]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "More than 7,000 stone tools have been dug from this cave. [SUPPORTED: https://web.archive.org/web/20251029123212/https://whc.unesco.org/en/tentativelists/6547/]; The cave is riverside (on the bank of a river). [SUPPORTED: https://web.archive.org/web/20251029123212/https://whc.unesco.org/en/tentativelists/6547/]; Stone Age people lived in the cave. [SUPPORTED: https://web.archive.org/web/20251029123212/https://whc.unesco.org/en/tentativelists/6547/]; The cave was inhabited in the Paleolithic (Stone Age) by people of the Mousterian culture. [SUPPORTED: https://web.archive.org/web/20251029123212/https://whc.unesco.org/en/tentativelists/6547/]; The cave has six layers. [SUPPORTED: https://web.archive.org/web/20251029123212/https://whc.unesco.org/en/tentativelists/6547/]; One of its layers held remains of mammals such as horse, noble deer and bull. [SUPPORTED: https://web.archive.org/web/20251029123212/https://whc.unesco.org/en/tentativelists/6547/]"}]'::jsonb),
    ('7e97d2a5-3f87-44fc-9ad0-f0d5a2d84cab'::uuid, 'card_description', 'On the western flank of the Santa Rita Mountains, a young girl exploring the crevices of Huerfano Butte found a small pottery jar filled with about 1,500 beads and pendants.', 'A young girl on a picnic found prehistoric jewelry on this small rocky hill. Granite outcrops on either side of a wash hold about fifty bedrock mortars and many smaller hollows.', 'teaser-card-s037:7e97d2a5-3f87-44fc-9ad0-f0d5a2d84cab:card_description', 'teaser-card-s037 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '39624bf3ef496003d4047d77190ed58a92940fbb7cb45bc6ce7500542039771c|79fb705fb2ebbd895d107e328188d607ed4230aedeeea99939d4d0b99da8718a|79fb705fb2ebbd895d107e328188d607ed4230aedeeea99939d4d0b99da8718a', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "A young girl on a picnic found prehistoric jewelry on this small rocky hill. Granite outcrops on either side of a wash hold about fifty bedrock mortars and many smaller hollows."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "a young girl found something here [S6, S7]; she was on a picnic when she found it [S6]; what she found was prehistoric jewelry [S6, S7]; the find was made on the site itself [S7]; the site is a small rocky hill (butte) [S1]; there are granite outcrops on either side of a wash [S4]; the outcrops hold about fifty bedrock mortars [S4]; the outcrops also hold many smaller hollows (cupules) [S4]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "A jewelry find was made on this hill (Huerfano Butte), the find it is known for. [SUPPORTED: https://research.fs.usda.gov/download/treesearch/36006.pdf]; The finder was a young girl. [SUPPORTED: https://research.fs.usda.gov/download/treesearch/36006.pdf]; She found it while on a picnic. [SUPPORTED: https://research.fs.usda.gov/download/treesearch/36006.pdf]; The jewelry was prehistoric. [SUPPORTED: https://research.fs.usda.gov/download/treesearch/36006.pdf]; The jewelry was found on the hill itself. [SUPPORTED: https://research.fs.usda.gov/download/treesearch/36006.pdf]; The hill is small. [SUPPORTED: https://research.fs.usda.gov/download/treesearch/36006.pdf]; The hill is rocky. [SUPPORTED: https://research.fs.usda.gov/download/treesearch/36006.pdf]; There is a wash (at the butte). [SUPPORTED: https://research.fs.usda.gov/download/treesearch/36006.pdf]; The outcrops on either side of the wash are granite. [SUPPORTED: https://research.fs.usda.gov/download/treesearch/36006.pdf]; The outcrops hold about fifty bedrock mortars. [SUPPORTED: https://research.fs.usda.gov/download/treesearch/36006.pdf]; The outcrops also hold many smaller hollows (cupules). [SUPPORTED: https://research.fs.usda.gov/download/treesearch/36006.pdf]"}]'::jsonb),
    ('9cf1ec14-dd93-4270-897f-158203e91758'::uuid, 'card_description', 'Over the entrance of Dun Dornaigil, an Iron Age broch in Sutherland, sits a massive triangular lintel, the wall there rising to nearly 7 metres. Inside, collapsed rubble bars the way.', 'Walls nearly 7 metres high still rise above the doorway of this Iron Age broch. Rubble fallen from the upper levels chokes the inside, and a massive triangular lintel spans the door.', 'teaser-card-s037:9cf1ec14-dd93-4270-897f-158203e91758:card_description', 'teaser-card-s037 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '409ded70a54df23bad4b8a45c5ea2cf0e331e1ee2f5c82cd9042fc0f2dcd347e|f731071f627ae91d53b5c84dd2e9e7bb26707b9f8b993c470e1f699893d3675b|f731071f627ae91d53b5c84dd2e9e7bb26707b9f8b993c470e1f699893d3675b', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Walls nearly 7 metres high still rise above the doorway of this Iron Age broch. Rubble fallen from the upper levels chokes the inside, and a massive triangular lintel spans the door."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "the walls above the doorway still rise to nearly 7 metres [S4]; it is an Iron Age broch [S1]; the interior is still filled with rubble [S7]; the rubble fell from the upper levels [S7]; a massive triangular lintel is over the entrance [S6]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Walls nearly 7 metres high still rise above the doorway of this broch [SUPPORTED: https://her.highland.gov.uk/Monument/MHG12928]; The site is a broch [SUPPORTED: https://her.highland.gov.uk/Monument/MHG12928]; The broch dates to the Iron Age [SUPPORTED: https://her.highland.gov.uk/Monument/MHG12928]; Rubble fallen from the upper levels chokes (fills) the inside [SUPPORTED: https://www.historicenvironment.scot/visit/all/dun-dornaigil-broch/]; A massive triangular lintel spans the door [SUPPORTED: https://her.highland.gov.uk/Monument/MHG12928]"}]'::jsonb),
    ('bbde3c09-ac95-4fe7-b9d9-1be1fd6452fb'::uuid, 'card_description', 'Glevum began as a Roman fort and in AD 97 became a colonia of retired legionaries, a city within the fortress ramparts, with a basilica, a forum market-place and homes with mosaic floors.', 'Retired Roman soldiers were given farmland around this town. The town rose inside the old fort, kept the fort''s street plan and ramparts, and gained fine homes with mosaic floors.', 'teaser-card-s037:bbde3c09-ac95-4fe7-b9d9-1be1fd6452fb:card_description', 'teaser-card-s037 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '988d579a50a0cd4650ed0c7f14f6b2cead19f58afc55c091eb688c966b5332e4|146e8b3801cdb0e0ad80c539a1e2733ce683dfdb4fde60d0334f315ff1498806|146e8b3801cdb0e0ad80c539a1e2733ce683dfdb4fde60d0334f315ff1498806', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Retired Roman soldiers were given farmland around this town. The town rose inside the old fort, kept the fort''s street plan and ramparts, and gained fine homes with mosaic floors."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "retired Roman soldiers (legionaries) settled the town [S1]; they were given farmland in the surrounding district [S4]; the town was built inside the old (legionary) fort [S1, S5]; the town kept the fort''s street plan [S5]; the town kept the fort''s ramparts [S5]; fine homes with mosaic floors were built in the town [S6]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "This town (Glevum) was a settlement of retired Roman soldiers (a colonia for veterans). [SUPPORTED: https://nora.nerc.ac.uk/id/eprint/8889/1/Chenery%20et%20al.%202010%20Roman%20Gloucester%20Isotopes.pdf]; The retired soldiers were given farmland around the town. [SUPPORTED: https://d2eq6t2r9q1quu.cloudfront.net/wp-content/uploads/cms/5/5.6a_The_Romans_in_Gloucester.pdf]; There was an older fort on the site before the town. [SUPPORTED: https://nora.nerc.ac.uk/id/eprint/8889/1/Chenery%20et%20al.%202010%20Roman%20Gloucester%20Isotopes.pdf]; The town rose inside the old fort. [SUPPORTED: https://www.encyclopedia.com/places/united-states-and-canada/us-political-geography/gloucester]; The town kept the fort''s street plan. [SUPPORTED: https://d2eq6t2r9q1quu.cloudfront.net/wp-content/uploads/cms/5/5.6a_The_Romans_in_Gloucester.pdf]; The town kept the fort''s ramparts. [SUPPORTED: https://www.encyclopedia.com/places/united-states-and-canada/us-political-geography/gloucester]; The town gained fine homes. [SUPPORTED: https://www.roman-britain.co.uk/places/glevum/]; Those homes had mosaic floors. [SUPPORTED: https://www.roman-britain.co.uk/places/glevum/]"}]'::jsonb),
    ('bcc037db-7637-44c9-8204-3ce6d4370653'::uuid, 'card_description', 'Its Woiwurrung name means axe place. At the Mount William Stone Axe Quarry, Aboriginal people dug greenstone from 268 mining pits and roughly flaked it into blanks for axe heads.', 'Aboriginal people mined greenstone from 268 pits at this site. Waste rock still lies in mounds up to 20 metres across, some with a central rock used as an anvil.', 'teaser-card-s037:bcc037db-7637-44c9-8204-3ce6d4370653:card_description', 'teaser-card-s037 (teaser-card): teaser card, 161 characters, checked PASS, web-verified VERIFIED', '23453fc712bc059a568b8c0ee3783154b37b31d1afc87c6831eb260d85545b5a|76a819cdbc8d29cc04778d85c3d1c2c2d722ac7be5e2030004eb12e47827218d|76a819cdbc8d29cc04778d85c3d1c2c2d722ac7be5e2030004eb12e47827218d', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Aboriginal people mined greenstone from 268 pits at this site. Waste rock still lies in mounds up to 20 metres across, some with a central rock used as an anvil."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Aboriginal people obtained greenstone here by mining [S3]; there are 268 mining pits [S5]; mounds of waste rock remain at the site today [S3, S5]; the mounds are up to 20 metres in diameter [S5]; some have a central rock used as an anvil [S5]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "Aboriginal people mined greenstone from 268 pits at this site [SUPPORTED: https://www.environment.gov.au/cgi-bin/ahdb/search.pl?mode=place_detail;place_id=105936]; Aboriginal people mined greenstone here [SUPPORTED: https://www.environment.gov.au/cgi-bin/ahdb/search.pl?mode=place_detail;place_id=105936]; Waste rock still lies in mounds at the site [SUPPORTED: https://www.environment.gov.au/cgi-bin/ahdb/search.pl?mode=place_detail;place_id=105936]; The mounds are up to 20 metres across [SUPPORTED: https://www.environment.gov.au/cgi-bin/ahdb/search.pl?mode=place_detail;place_id=105936]; Some mounds have a central rock used as an anvil [SUPPORTED: https://www.environment.gov.au/cgi-bin/ahdb/search.pl?mode=place_detail;place_id=105936]"}]'::jsonb),
    ('e9a3f325-9632-4f10-a0a4-b04048f0b117'::uuid, 'card_description', 'At Tegea, the Temple of Athena Alea honoured a goddess fused from Olympian Athena and the local deity Alea. Endoeus made her cult statue in ivory; Pausanias told of the first temple.', 'An ivory cult statue by Endoeus once stood in this sanctuary. Tests on slag found in front of its Geometric temple confirmed that metal was worked there at that time.', 'teaser-card-s037:e9a3f325-9632-4f10-a0a4-b04048f0b117:card_description', 'teaser-card-s037 (teaser-card): teaser card, 166 characters, checked PASS, web-verified VERIFIED', 'f5309cd50298f3f34192933e445f555f376c0d9f3a940a024c46eb2df250cff4|6648786c6fe8cc12721a56e49d05414fad5ff22f8df6f949261735e0896f6d78|6648786c6fe8cc12721a56e49d05414fad5ff22f8df6f949261735e0896f6d78', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "An ivory cult statue by Endoeus once stood in this sanctuary. Tests on slag found in front of its Geometric temple confirmed that metal was worked there at that time."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "the sanctuary had a cult statue [S4]; the cult statue was of ivory [S4]; the cult statue was made by Endoeus [S4]; the statue once stood in this sanctuary [S1, S4]; the sanctuary had a Geometric temple [W1]; slag was found in front of the Geometric temple [W1]; analyses of the slag confirmed metalworking in the sanctuary in that (Geometric) period [W1]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "A cult statue by Endoeus once stood in this sanctuary (of Athena Alea at Tegea). [SUPPORTED: https://www.theoi.com/Text/Pausanias8C.html]; The cult statue was made of ivory. [SUPPORTED: https://www.theoi.com/Text/Pausanias8C.html]; The statue stood in the sanctuary only once, i.e. it is no longer there (it was removed). [SUPPORTED: https://www.theoi.com/Text/Pausanias8C.html]; The sanctuary had a temple of the Geometric period. [SUPPORTED: https://chronique.efa.gr/?r=report&id=13594]; Slag was found in front of the Geometric temple. [SUPPORTED: https://chronique.efa.gr/?r=report&id=13593]; Tests (analyses) were carried out on that slag. [SUPPORTED: https://chronique.efa.gr/?r=report&id=13593]; The tests confirmed that metal was worked in the sanctuary. [SUPPORTED: https://chronique.efa.gr/?r=report&id=13736]; The metalworking dates to the time of the Geometric temple. [SUPPORTED: https://chronique.efa.gr/?r=report&id=13593]"}, {"source": "web fact W1", "url": "https://chronique.efa.gr/?r=report&id=13593", "quote": "Les analyses de scories recueillies devant le temple géométrique ont confirmé l''existence d''activités métallurgiques dans le sanctuaire à cette époque."}]'::jsonb),
    ('f0b786ae-17e0-4ce1-bfdc-c9184e5473a3'::uuid, 'card_description', 'In a cave of the Swabian Jura, Hohlenstein-Stadel gave up the Löwenmensch, a small ivory statue among the oldest figurative art ever found, and a femur that DNA showed was a Neanderthal''s.', 'A small ivory statue called the Löwenmensch came from this cave. The statue is among the oldest pieces of figurative art ever found, and a thigh bone from the cave belonged to a Neanderthal.', 'teaser-card-s037:f0b786ae-17e0-4ce1-bfdc-c9184e5473a3:card_description', 'teaser-card-s037 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', 'a7cbdf5ff377004118ec6d5d4a9341ecae584d707f754533b6cb615d2b108fce|7503c6296a288812a82cc1b865a050e136ace9d18efb79c43442b4ac52558000|7503c6296a288812a82cc1b865a050e136ace9d18efb79c43442b4ac52558000', '[{"source": "lane WB run wb-shorts-pilot2-2026-10-19: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "A small ivory statue called the Löwenmensch came from this cave. The statue is among the oldest pieces of figurative art ever found, and a thigh bone from the cave belonged to a Neanderthal."}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "a small ivory statue called the Lowenmensch was found here [S2]; the site is a cave [S1]; the statue is one of the oldest pieces of figurative art ever found [S2]; a thigh bone was found in the cave [S4]; the thigh bone belonged to a Neanderthal [S7]"}, {"source": "lane WB run wb-shorts-pilot2-2026-10-19: verifier card_web_verifier:teaser-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot2-2026-10-19/OUTCOMES.jsonl", "quote": "The Löwenmensch statue came from this cave (Hohlenstein-Stadel). [SUPPORTED: https://museumulm.de/en/collections/archaeology/]; The statue is called the Löwenmensch. [SUPPORTED: https://museumulm.de/en/collections/archaeology/]; The statue is made of ivory. [SUPPORTED: https://museumulm.de/en/collections/archaeology/]; The statue is small. [SUPPORTED: https://en.wikipedia.org/wiki/Lion-man_of_Hohlenstein-Stadel]; The statue is among the oldest pieces of figurative art ever found. [SUPPORTED: https://museumulm.de/en/collections/archaeology/]; A thigh bone (femur) from the cave belonged to a Neanderthal. [SUPPORTED: https://www.nature.com/articles/ncomms16046]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 23;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s037', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s037'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s037'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 23 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s037'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s037' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
